(()=>{const EVENTS=new Set(['ebook_impression','ebook_view','ebook_amazon_click','ebook_preview_open','ebook_preview_signup','newsletter_view','newsletter_submit','newsletter_success','podcast_episode_view','podcast_play','podcast_30_seconds','bundle_view','bundle_book_click','book_finder_start','book_finder_complete']);const KEYS=['book_slug','topic','page_type','placement','referrer_group','campaign','bundle_slug','episode_slug'];const clean=v=>String(v||'').replace(/[\r\n\t]/g,' ').trim().slice(0,100);const pageType=()=>document.body?.dataset.pageType||(/^\/ebooks\/[^/]+\/$/.test(location.pathname)?'ebook':location.pathname.startsWith('/ebooks/')?'ebook':location.pathname.startsWith('/podcast/episodes/')?'podcast_episode':location.pathname==='/podcast/'?'podcast':location.pathname.startsWith('/bundles/')?'reading_path':location.pathname==='/'?'home':'page');const refGroup=()=>{if(!document.referrer)return'direct';try{const h=new URL(document.referrer).hostname;if(h===location.hostname)return'internal';if(/google|bing|duckduckgo|yahoo/.test(h))return'search';if(/facebook|instagram|tiktok|linkedin|x\.com|twitter|youtube/.test(h))return'social';return'referral'}catch{return'referral'}};const campaign=()=>clean(new URLSearchParams(location.search).get('utm_campaign'));function track(event,d={}){if(!EVENTS.has(event))return false;const payload={event};const common={page_type:pageType(),referrer_group:refGroup(),campaign:campaign()};for(const k of KEYS){const v=d[k]??common[k];if(v)payload[k]=clean(v)}window.dataLayer=window.dataLayer||[];window.dataLayer.push(payload);return true}window.JHAnalytics={track,events:[...EVENTS]};const once=new WeakSet;const onceKey=new Set;function dims(el,placement){return{book_slug:el?.dataset.bookSlug||document.body?.dataset.bookSlug,topic:el?.dataset.topic||document.body?.dataset.topic,placement:el?.dataset.placement||placement,bundle_slug:el?.dataset.bundleSlug||document.body?.dataset.bundleSlug,episode_slug:el?.dataset.episodeSlug||document.body?.dataset.episodeSlug}}function wire(){const body=document.body;if(body?.dataset.bookSlug)track('ebook_view',dims(body,'ebook_page'));if(body?.dataset.bundleSlug)track('bundle_view',dims(body,'reading_path'));if(body?.dataset.episodeSlug||location.pathname.startsWith('/podcast/episodes/'))track('podcast_episode_view',dims(body,'podcast_episode'));document.addEventListener('click',e=>{const a=e.target.closest('[data-ebook-amazon],[data-ebook-preview],[data-bundle-book-click]');if(!a)return;if(a.matches('[data-ebook-amazon]'))track('ebook_amazon_click',dims(a,'unknown'));if(a.matches('[data-ebook-preview]'))track('ebook_preview_open',dims(a,'ebook_page'));if(a.matches('[data-bundle-book-click]'))track('bundle_book_click',dims(a,'reading_path'))},{capture:true});const io='IntersectionObserver'in window?new IntersectionObserver(entries=>entries.forEach(x=>{if(!x.isIntersecting||once.has(x.target))return;once.add(x.target);if(x.target.matches('.ebook-card[data-book-slug]'))track('ebook_impression',dims(x.target,'catalogue_card'));if(x.target.matches('[data-newsletter-shell]'))track('newsletter_view',{placement:x.target.dataset.newsletterSource||'newsletter'})}),{threshold:.35}):null;document.querySelectorAll('.ebook-card[data-book-slug],[data-newsletter-shell]').forEach(el=>io?io.observe(el):null);document.querySelectorAll('audio[data-latest-audio],audio[data-podcast-audio]').forEach(audio=>{audio.addEventListener('play',()=>{const k='play:'+clean(audio.dataset.episodeSlug||location.pathname);if(!onceKey.has(k)){onceKey.add(k);track('podcast_play',{episode_slug:audio.dataset.episodeSlug||'',placement:audio.dataset.placement||'podcast_player'})}});audio.addEventListener('timeupdate',()=>{if(audio.currentTime<30)return;const k='30:'+clean(audio.dataset.episodeSlug||location.pathname);if(!onceKey.has(k)){onceKey.add(k);track('podcast_30_seconds',{episode_slug:audio.dataset.episodeSlug||'',placement:audio.dataset.placement||'podcast_player'})}})})}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',wire,{once:true}):wire()})();
